 const container=$('#performanceColumns');
 function build(cols){container.className='performance-columns cols-'+cols;container.innerHTML='';const cs=[];for(let i=0;i<cols;i++){const c=document.createElement('div');c.className='performance-column';container.append(c);cs.push(c)};if(cols===1){blocks.forEach(b=>{const d=document.createElement('div');d.className='performance-verse';d.textContent=b;cs[0].append(d)});return cs}
 const weights=blocks.map(b=>b.split('\n').length+Math.ceil(b.length/55)*.45);let total=weights.reduce((a,b)=>a+b,0),acc=0,cut=1,best=Infinity;for(let i=1;i<blocks.length;i++){acc+=weights[i-1];const score=Math.abs(total-2*acc);if(score<best){best=score;cut=i}}blocks.forEach((b,i)=>{const d=document.createElement('div');d.className='performance-verse';d.textContent=b;cs[i<cut?0:1].append(d)});return cs}
 let manualDelta=0;
